<script>
const products=@json($saleProducts);const cart=new Map(),tbody=document.getElementById('cart'),submit=document.getElementById('submit-sale');function render(){tbody.innerHTML='';document.getElementById('hidden-items').innerHTML='';let subtotal=0;for(const p of cart.values()){const rowTotal=p.price*p.qty;subtotal+=rowTotal;const tr=document.createElement('tr');tr.innerHTML=`<td>${escapeHtml(p.name)}</td><td><input aria-label="จำนวน ${escapeHtml(p.name)}" type="number" min="1" max="${p.stock}" value="${p.qty}" style="width:74px;padding:7px" data-qty="${p.id}"></td><td>฿${rowTotal.toFixed(2)}</td><td><button class="btn small danger" type="button" data-remove="${p.id}">×</button></td>`;tbody.appendChild(tr)}const discount=Math.max(0,Number(document.getElementById('discount').value||0));document.getElementById('subtotal').textContent='฿'+subtotal.toFixed(2);document.getElementById('discount-view').textContent='฿'+discount.toFixed(2);document.getElementById('total').textContent='฿'+Math.max(0,subtotal-discount).toFixed(2);document.getElementById('cart-empty').style.display=cart.size?'none':'block';submit.disabled=cart.size===0||discount>subtotal;for(const p of cart.values()){const i=document.createElement('input');i.type='hidden';i.name=`items[${p.id}][product_id]`;i.value=p.id;document.getElementById('hidden-items').appendChild(i);const q=document.createElement('input');q.type='hidden';q.name=`items[${p.id}][quantity]`;q.value=p.qty;q.dataset.hiddenQty=p.id;document.getElementById('hidden-items').appendChild(q)}}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}document.querySelectorAll('.add-item').forEach(b=>b.addEventListener('click',()=>{const p=products.find(x=>x.id===Number(b.dataset.id));if(!p)return;const current=cart.get(p.id);if(current&&current.qty>=p.stock)return;if(p.type==='account'&&current)return;cart.set(p.id,{...p,qty:(current?.qty||0)+1});render()}));document.getElementById('cart').addEventListener('input',e=>{if(e.target.dataset.qty){const p=cart.get(Number(e.target.dataset.qty));p.qty=Math.min(p.stock,Math.max(1,Number(e.target.value)||1));document.querySelector(`[data-hidden-qty="${p.id}"]`).value=p.qty;render()}});document.getElementById('cart').addEventListener('click',e=>{if(e.target.dataset.remove){cart.delete(Number(e.target.dataset.remove));render()}});document.getElementById('discount').addEventListener('input',render);document.getElementById('payment-status').addEventListener('change',e=>document.getElementById('method-field').style.display=e.target.value==='paid'?'block':'none');document.getElementById('product-search').addEventListener('input',e=>document.querySelectorAll('#product-list tr[data-search]').forEach(row=>row.style.display=row.dataset.search.includes(e.target.value.toLowerCase())?'':'none'));render();
</script>
